// İki giriş de buradan geçer:
//  • Webhook ile gelen istekte alanlar "body" içindedir,
//  • Workflow 05'in "/oku" komutuyla yaptığı çağrıda doğrudan gelir.
const j = $input.first().json || {};
const webhooktan = Object.prototype.hasOwnProperty.call(j, 'body');
const govde = webhooktan ? (j.body || {}) : j;
return [{ json: {
  ham: String(govde.url || govde.baglanti || govde.text || '').trim(),
  chat_id: govde.chat_id ? String(govde.chat_id) : '',
  etiket: String(govde.etiket || '').trim(),
  webhooktan,
} }];

// Okuma zinciri hata verdiyse: dosya gerçekten YOKSA boş listeyle devam edilir,
// ama dosya bozuk/erişilemez ise çalışma durdurulur — aksi hâlde liste boş
// sanılıp üzerine yazılır ve veriler kaybolur.
const _dosyaKontrol = (okuNode, cikarNode, dosya) => {
  const okuHata = $(okuNode).first().json.error;
  const okuMesaj = okuHata ? String(okuHata.message || okuHata) : '';
  if (/ENOENT|no such file|not found/i.test(okuMesaj)) return; // dosya henüz oluşmamış
  const cikarHata = $(cikarNode).first().json.error;
  if (okuHata || cikarHata) {
    const m = okuMesaj || String((cikarHata && cikarHata.message) || cikarHata);
    throw new Error(dosya + ' okunamadı; okuma listesi korunsun diye durduruldu → ' + m);
  }
};
_dosyaKontrol('Okunacakları Oku', 'Okunacakları Çıkar', 'okunacaklar.json');


// Gelen bağlantıyı doğrular ve daha önce kaydedilmiş mi diye bakar.
const istek = $('İsteği Al (Link)').first().json || {};
const ham = istek.ham;
const chatId = istek.chat_id;
const etiket = istek.etiket;
const webhooktan = istek.webhooktan;

const okunan = $('Okunacakları Çıkar').first().json || {};
const d = (okunan.data && okunan.data.baglantilar) || [];
const baglantilar = Array.isArray(d) ? d.map((x) => ({ ...x })) : [];

// Metnin içinden ilk http(s) adresini al — Telegram'dan gelen "/oku <url>" için.
const eslesme = ham.match(/https?:\/\/[^\s<>"']+/i);
const url = eslesme ? eslesme[0].replace(/[.,;)]+$/, '') : '';

if (!url) {
  return [{ json: {
    gecerli: false, chatId, webhooktan, baglantilar, yazilsin: false,
    mesaj: 'Geçerli bir bağlantı bulunamadı. Örnek: {"url": "https://ornek.com/yazi"}',
  } }];
}

const varOlan = baglantilar.find((b) => b && b.url === url);
if (varOlan) {
  return [{ json: {
    gecerli: false, chatId, webhooktan, baglantilar, yazilsin: false,
    mesaj: '🔖 Bu bağlantı zaten listede:\n' + (varOlan.baslik || varOlan.url) +
           (varOlan.ozet ? '\n\n' + varOlan.ozet : ''),
  } }];
}

return [{ json: {
  gecerli: true, url, chatId, webhooktan, etiket, baglantilar,
  model: String($env.OLLAMA_MODEL || 'qwen2.5:3b').trim(),
} }];

// Yalnızca geçerli ve yeni bağlantılar için sayfa indirilir.
const j = $input.first().json;
return j.gecerli ? [{ json: j }] : [];

// Geçersiz ya da zaten kayıtlı bağlantılar buradan geçer (sayfa indirilmez).
const j = $input.first().json;
if (j.gecerli) return [];
return [{ json: { mesaj: j.mesaj, chatId: j.chatId, webhooktan: j.webhooktan, baglantilar: j.baglantilar, yazilsin: false } }];

// HTML'i sade metne çevirir: script/style atılır, etiketler silinir,
// boşluklar tek boşluğa indirilir. Modele en fazla ~6000 karakter gider.
const hazirlik = $('Bağlantıyı Doğrula').first().json || {};
const yanit = $input.first().json || {};

if (yanit.error) {
  const ham = String(yanit.error.message || yanit.error);
  return [{ json: { ...hazirlik, indirilemedi: true, hataMesaji: ham.slice(0, 200), metin: '', baslik: '' } }];
}

const html = String(yanit.data || '');
const basligiBul = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
const ozellikBul = (ad) => {
  const m = html.match(new RegExp('<meta[^>]+(?:property|name)=["\']' + ad + '["\'][^>]*>', 'i'));
  if (!m) return '';
  const i = m[0].match(/content=["']([^"']*)["']/i);
  return i ? i[1] : '';
};

const cozumle = (s) => String(s)
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
  .replace(/&[a-z]+;/gi, ' ');

const baslik = cozumle(ozellikBul('og:title') || (basligiBul ? basligiBul[1] : '')).trim().slice(0, 200);
const aciklama = cozumle(ozellikBul('og:description') || ozellikBul('description')).trim().slice(0, 500);

const metin = cozumle(
  html
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<(br|\/p|\/div|\/li|\/h[1-6])>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
).replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim().slice(0, 6000);

// Sayfa JavaScript ile yükleniyorsa metin çok kısa çıkar; o zaman meta açıklamayı kullan.
const yeterli = metin.length >= 300;

return [{ json: { ...hazirlik, indirilemedi: false, baslik, aciklama, metin, yeterli } }];

// Metin yeterliyse modele gider; değilse (JS ile yüklenen sayfa, indirilemedi)
// model çağrılmaz — uydurma özet üretmesin.
const j = $input.first().json;
if (j.indirilemedi || !j.yeterli) return [];
return [{ json: j }];

// Modele gitmeyen sayfalar: indirilemedi ya da metin çok kısa.
const j = $input.first().json;
if (!j.indirilemedi && j.yeterli) return [];
return [{ json: { ...j, ozet: '' } }];

