// Özeti (varsa) listeye ekler ve gönderilecek metni kurar.
const hazirlik = $('Metni Ayıkla').first().json || {};
const giris = $input.first().json || {};

// Bu düğüm iki koldan beslenir: model kolu Ollama yanıtını, atlama kolu
// doğrudan hazırlığı getirir. Hangisinden geldiğini yanıtın şeklinden anlarız.
const modeldenGeldi = Object.prototype.hasOwnProperty.call(giris, 'response') ||
                      Object.prototype.hasOwnProperty.call(giris, 'error');
let ozet = '';
let uyari = '';

if (modeldenGeldi) {
  if (giris.error || !giris.response) {
    const ham = String((giris.error && (giris.error.message || giris.error.description)) || giris.error || '');
    uyari = /econnrefused|enotfound|getaddrinfo/i.test(ham)
      ? 'Ollama kapalı — özet üretilmedi (bağlantı yine kaydedildi).'
      : 'Özet üretilemedi (bağlantı yine kaydedildi).';
  } else {
    ozet = String(giris.response).trim().slice(0, 1500);
  }
} else if (giris.indirilemedi) {
  uyari = 'Sayfa indirilemedi (' + (giris.hataMesaji || 'erişilemedi') + ') — bağlantı yine kaydedildi.';
} else {
  uyari = 'Sayfa metni okunamadı (JavaScript ile yükleniyor olabilir) — özet üretilmedi.';
}

const url = hazirlik.url;
const baslik = hazirlik.baslik || url;
const baglantilar = Array.isArray(hazirlik.baglantilar) ? hazirlik.baglantilar.map((x) => ({ ...x })) : [];
const id = baglantilar.reduce((mx, x) => Math.max(mx, Number(x.id) || 0), 0) + 1;

baglantilar.push({
  id, url, baslik,
  ozet: ozet || hazirlik.aciklama || '',
  etiket: hazirlik.etiket || '',
  okundu: false,
  eklenme: new Date().toISOString(),
});

const govde = ozet || hazirlik.aciklama || '';
const mesaj = ['🔖 #' + id + ' ' + baslik, url, govde ? '\n' + govde : '', uyari ? '\n⚠️ ' + uyari : '']
  .filter(Boolean).join('\n');

return [{ json: { mesaj, chatId: hazirlik.chatId, webhooktan: hazirlik.webhooktan, baglantilar, yazilsin: true, id, baslik, url, ozet: govde } }];

// Yanıt düğümü yalnızca webhook ile gelen isteklerde çalışmalı;
// workflow 05'ten gelen çağrıda yanıtlanacak bir HTTP isteği yoktur.
const j = $input.first().json;
return j.webhooktan ? [{ json: j }] : [];

// İstek Telegram'dan geldiyse (chat_id doluysa) sonuç oraya da gider.
const j = $input.first().json;
if (!j.chatId) return [];
return [{ json: { chat_id: j.chatId, text: String(j.mesaj).slice(0, 3900) } }];

// Dosyaya yalnızca bağlantı listesi yazılır.
const j = $input.first().json;
if (!j.yazilsin) return [];
return [{ json: { baglantilar: j.baglantilar } }];
